<?php declare(strict_types=1);require __DIR__.'/_bootstrap.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$slide=['eyebrow'=>'','title'=>'','subtitle'=>'','image_path'=>'','cta_text'=>'Shop Fabrics','cta_link'=>'#fabrics','is_active'=>1,'sort_order'=>0];if($id){$s=$pdo->prepare('SELECT * FROM hero_slides WHERE id=?');$s->execute([$id]);$slide=$s->fetch()?:$slide;}$error='';
