$pageTitle=$id?'Edit Hero Slide':'Add Hero Slide';$active='slides';require __DIR__.'/includes/layout.php';if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><div class="panel form-card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><div class="field"><label>Eyebrow</label><input name="eyebrow" value="<?=e($slide['eyebrow'])?>" placeholder="BENAKI FABRICS"></div><div class="field"><label>Title *</label><input name="title" value="<?=e($slide['title'])?>" required></div><div class="field"><label>Subtitle</label><textarea name="subtitle" rows="4"><?=e($slide['subtitle'])?></textarea></div><div class="field"><label>Slide image <?= $id?'(leave empty to keep current)':'*' ?></label><?php if($slide['image_path']): ?><img class="preview" src="../<?=e($slide['image_path'])?>" alt=""><?php endif;?><input name="image" type="file" accept="image/jpeg,image/png,image/webp" <?= $id?'':'required' ?>></div><div class="grid2"><div class="field"><label>CTA text</label><input name="cta_text" value="<?=e($slide['cta_text'])?>"></div><div class="field"><label>CTA link</label><input name="cta_link" value="<?=e($slide['cta_link'])?>" placeholder="#order or https://..."></div></div><div class="grid2"><div class="field"><label>Display order</label><input name="sort_order" type="number" value="<?=e($slide['sort_order'])?>"></div><div class="field"><label>Visibility</label><label class="check"><input type="checkbox" name="is_active" <?=!empty($slide['is_active'])?'checked':''?>> Show on homepage</label></div></div><div style="display:flex;gap:8px"><button class="btn btn-gold">Save slide</button><a class="btn btn-light" href="slides.php">Cancel</a></div></form></div><?php require __DIR__.'/includes/footer.php';?>
